CSS=r''':root{--bg:#f2eee5;--paper:#fbf8f1;--ink:#11110f;--muted:#716b60;--gold:#967b43;--gold2:#c4aa72;--line:#d7d0c3;--black:#0d0d0c;--radius:18px;--shadow:0 18px 48px rgba(20,16,8,.08)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Tahoma,"Segoe UI",Arial,sans-serif;line-height:1.9;text-rendering:optimizeLegibility}button,a{font:inherit}a{color:inherit}.shell{max-width:1220px;margin:0 auto;padding:clamp(42px,6vw,82px) clamp(18px,4vw,52px)}.layer-1{min-height:min(840px,100svh);background:var(--black);color:#f7f2e8;padding:clamp(28px,5vw,64px) max(22px,calc((100vw - 1220px)/2 + 52px));display:flex;flex-direction:column;justify-content:center}.hero-top{display:flex;justify-content:space-between;gap:30px;align-items:flex-start}.eyebrow,.section-kicker{font-size:12px;letter-spacing:.14em;color:var(--gold2);font-weight:700}.hero h1{font-size:clamp(34px,5vw,68px);margin:4px 0 0;line-height:1.1}.request{color:#bdb6a8;margin:12px 0 0;max-width:720px}.asof{text-align:left;color:#d8d0c2;direction:ltr}.asof small{display:block;color:#8f887d}.focus-answer{margin:clamp(26px,5vw,62px) 0 26px;max-width:940px}.focus-answer span{display:block;color:var(--gold2);font-size:13px}.focus-answer strong{display:block;font-size:clamp(23px,3.3vw,44px);line-height:1.55;margin-top:8px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:1px;background:#2c2924;border:1px solid #2c2924;border-radius:14px;overflow:hidden}.metric{background:#161513;padding:15px 17px;min-height:88px}.metric span{display:block;color:#9f988d;font-size:12px}.metric strong{font-size:17px}.metric small{display:block;color:#8e877a}.now-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:20px}.now-card{border-top:1px solid #3a352c;padding:17px 0}.now-card span{color:var(--gold2);font-size:12px}.now-card p{margin:3px 0;color:#ddd5c8}.down{margin-top:18px;color:#a99d89;text-decoration:none;width:max-content}.section-kicker{color:var(--gold)}h2{font-size:clamp(22px,2.5vw,34px);line-height:1.4;margin:8px 0 12px}.lead{color:var(--muted);max-width:760px}.analysis-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:30px 0 46px}.analysis-card{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow);display:flex;flex-direction:column;min-height:275px}.card-head{display:flex;justify-content:space-between;gap:12px}.card-head h3{margin:0;font-size:19px}.relation{color:var(--muted);font-size:12px}.state{font-size:12px;border:1px solid var(--line);border-radius:999px;padding:4px 9px;height:max-content}.analysis-card p{color:#34312c;margin:18px 0}.important{margin-top:auto;padding:13px 0;border-top:1px solid var(--line);font-size:13px}.important span{display:block;color:var(--gold);font-size:11px}.deep-button{margin-top:14px;align-self:flex-start;border:0;background:var(--black);color:white;border-radius:999px;padding:9px 17px;cursor:pointer}.deep-button:focus-visible,button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #c7a858;outline-offset:3px}.split{display:grid;grid-template-columns:1.15fr .85fr;gap:16px}.panel{background:rgba(251,248,241,.75);border:1px solid var(--line);border-radius:var(--radius);padding:24px;margin:16px 0}.drivers{margin:0}.drivers div,dl div{display:grid;grid-template-columns:170px 1fr;border-bottom:1px solid var(--line);padding:9px 0}.drivers dt,dt{color:var(--muted)}dd{margin:0}.causal-chain{display:flex;flex-direction:column;align-items:center;gap:3px;background:#151411;color:white;padding:18px;border-radius:14px}.causal-chain span:not(.arrow){padding:5px 12px;text-align:center}.arrow{color:var(--gold2)}.causal-note{font-size:13px;color:var(--muted)}.pressure-list{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}.pressure-list .metric{background:var(--paper);color:var(--ink);min-height:90px}.pressure-list .metric span{color:var(--muted)}.scenario-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.scenario{border-top:2px solid var(--gold);background:var(--paper);padding:18px}.scenario h4{margin:0}.scenario-direction{color:var(--gold);font-size:12px}.health{padding-top:0}.health>details,.audit>details{border-top:1px solid var(--line);padding:18px 0}.health summary,.audit summary{cursor:pointer;font-weight:700;display:flex;justify-content:space-between}.health summary small{color:var(--muted);font-weight:400}.nested{margin-top:15px}pre{direction:ltr;text-align:left;white-space:pre-wrap;overflow:auto;background:#111;color:#eee;padding:16px;border-radius:12px;font-size:11px;line-height:1.65}dialog{width:min(1040px,94vw);height:min(900px,92vh);border:0;padding:0;border-radius:24px;background:var(--paper);box-shadow:0 30px 100px rgba(0,0,0,.35)}dialog::backdrop{background:rgba(5,5,4,.65);backdrop-filter:blur(6px)}.dialog-shell{height:100%;display:flex;flex-direction:column}.dialog-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding:24px 30px;background:var(--paper);position:sticky;top:0;z-index:2}.dialog-head h2{margin:3px 0}.close{border:0;background:transparent;font-size:34px;cursor:pointer}.deep-content{padding:20px 30px 34px;overflow:auto}.deep-simple{font-size:19px;background:#eee7d9;border-right:3px solid var(--gold);padding:15px}.deep-section{border-top:1px solid var(--line);padding:17px 0}.deep-section h3{font-size:15px;margin:0 0 8px}.deep-section ul{margin:0}.dialog-nav{margin-top:auto;border-top:1px solid var(--line);padding:13px 30px;display:flex;justify-content:space-between;gap:10px;background:var(--paper)}.dialog-nav button{border:1px solid var(--line);background:transparent;border-radius:999px;padding:8px 14px;cursor:pointer}.audit{padding-top:0;padding-bottom:80px}.muted{color:var(--muted)}@media(max-width:850px){.metrics{grid-template-columns:repeat(2,1fr)}.analysis-grid,.split,.now-grid{grid-template-columns:1fr}.hero-top{display:block}.asof{text-align:right;margin-top:15px}.drivers div,dl div{grid-template-columns:1fr}.pressure-list{grid-template-columns:1fr 1fr}}@media(max-width:520px){.layer-1{min-height:auto;padding-top:40px;padding-bottom:44px}.metrics{grid-template-columns:1fr 1fr}.metric{min-height:78px;padding:12px}.analysis-card{min-height:auto}.dialog-head,.deep-content,.dialog-nav{padding-left:18px;padding-right:18px}.dialog-nav{font-size:12px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}@media print{body{background:#fff}.layer-1{min-height:auto;background:#fff;color:#000;padding:28px}.focus-answer strong{font-size:25px}.metrics{border:1px solid #aaa}.metric{background:#fff;color:#000;border:1px solid #ddd}.analysis-grid{display:block}.analysis-card{box-shadow:none;margin:10px 0;break-inside:avoid}.deep-button,dialog,.down{display:none}.shell{padding:22px}}'''

JS=r'''(()=>{const d=document.getElementById('deep-dialog'),data=JSON.parse(document.getElementById('deep-data').textContent),body=document.getElementById('deep-body'),title=document.getElementById('deep-title'),keys=Object.keys(data);let idx=0;const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const list=(a,empty='مورد مهمی ثبت نشده است.')=>{a=(a||[]).filter(Boolean);return '<ul>'+((a.length?a:[empty]).map(x=>'<li>'+esc(x)+'</li>').join(''))+'</ul>'};function section(h,a){return '<section class="deep-section"><h3>'+h+'</h3>'+list(a)+'</section>'}function show(k){idx=Math.max(0,keys.indexOf(k));const x=data[keys[idx]];title.textContent=x.title_fa||'جزئیات بخش';body.innerHTML='<div class="deep-content"><p class="deep-simple">'+esc(x.simple_result_fa)+'</p>'+section('چه چیزی مشاهده شده؟',x.observations_fa)+section('چرا مهم است؟',x.why_it_matters_fa)+section('چه چیزی این نتیجه را تأیید می‌کند؟',x.support_fa)+section('چه چیزی با آن مخالف است؟',x.opposition_fa)+section('چه چیزی هنوز نامعلوم است؟',x.unknowns_fa)+section('مکانیزم اثر روی بازار',x.mechanism_fa)+section('چه چیزی این تحلیل را تغییر می‌دهد؟',x.invalidation_fa)+'<section class="deep-section"><h3>ارتباط با جهت فعلی</h3><p>'+esc(x.relation_to_direction_fa)+'</p></section><section class="deep-section"><h3>افق زمانی</h3><p>'+esc(x.horizon_fa)+'</p></section><details class="deep-section"><summary>شواهد کامل</summary><pre>'+esc(JSON.stringify(x.evidence_refs||[],null,2))+'</pre></details><details class="deep-section"><summary>جزئیات فنی</summary><pre>'+esc(JSON.stringify(x.technical_detail||{},null,2))+'</pre></details></div>';if(!d.open)d.showModal()}document.querySelectorAll('[data-deep]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.deep)));document.querySelectorAll('.close,.back-overview').forEach(b=>b.addEventListener('click',()=>d.close()));document.getElementById('deep-prev').addEventListener('click',()=>show(keys[(idx-1+keys.length)%keys.length]));document.getElementById('deep-next').addEventListener('click',()=>show(keys[(idx+1)%keys.length]));d.addEventListener('click',e=>{if(e.target===d)d.close()})})();'''

def explorer_html(model,view='EXPLORER'):
    model=dict(model); model['ux']=dict(model.get('ux') or {}); model['ux']['active_view']=view
    subject=str(model.get('header',{}).get('subject') or 'Alpha Lab')
    return f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Alpha Lab — {subject}</title><style>{CSS}</style></head><body><main>{layer1(model)}{layer2(model)}{method_and_apl(model)}{audit(model)}{deep_dialog(model)}</main><script>{JS}</script></body></html>'''

def render_files(out_dir,model,profile='EXPLORER'):
    out=Path(out_dir);out.mkdir(parents=True,exist_ok=True);rid=model['audit']['run_id'];stem=rid+'_'+profile.lower();jp=out/(stem+'.report.json');hp=out/(stem+'.html');jp.write_text(json.dumps(model,ensure_ascii=False,indent=2,sort_keys=True)+'\n',encoding='utf-8');hp.write_text(explorer_html(model,profile),encoding='utf-8')
    return {'report_model_path':str(jp),'html_path':str(hp),'pdf_path':None,'profile':profile,'ux_version':'UI2.0.0'}

def render_pdf_from_html(html_path,pdf_path):
    candidates=[shutil.which('msedge'),shutil.which('msedge.exe'),shutil.which('chrome'),shutil.which('chrome.exe'),shutil.which('chromium'),shutil.which('chromium-browser')]
    exe=next((x for x in candidates if x),None)
    if not exe:return {'status':'PENDING','reason':'NO_HEADLESS_BROWSER_FOUND','pdf_path':None}
    p=Path(pdf_path).resolve();u=Path(html_path).resolve().as_uri();q=subprocess.run([exe,'--headless','--disable-gpu','--no-pdf-header-footer','--print-to-pdf='+str(p),u],capture_output=True,text=True,timeout=120)
    return {'status':'PASS' if q.returncode==0 and p.is_file() else 'FAIL','pdf_path':str(p) if p.is_file() else None,'stderr':q.stderr[-2000:]}
